from lib import *
S = SS('x18')
steps = [
    step("启动时间。n 个 Heavy 单例,构造器各睡 20 ms。10 个:饿汉 refresh() 312 ms,已创建的单例 23 个;懒加载 refresh() 65 ms,单例 18 个,之后第一次取其中 5 个花 124 ms,再取这 5 个 0 ms。50 个:饿汉 refresh() 1263 ms,单例 63 个;懒加载 refresh() 86 ms,单例仍是 18 个,第一次取 5 个 127 ms,再取 0 ms。懒加载把构造的代价从启动挪到了第一次使用,总工作量没少。", t=tl(S(1)), mark=lidx(S(1), '懒加载 50 个', '懒加载 10 个'), done=lidx(S(1), '饿汉 50 个', '饿汉 10 个'), b=bars([['饿汉 50 个:refresh ms', 1263, '1263'], ['懒加载 50 个:refresh ms', 86, '86'], ['懒加载 50 个:第一次取 5 个 ms', 127, '127'], ['饿汉 10 个:refresh ms', 312, '312'], ['懒加载 10 个:refresh ms', 65, '65']], 1263, done=[0, 3], mark=[1, 4], cur=[2]), kv=KV([['饿汉 50 个', 'refresh 1263 ms,63 个单例'], ['懒加载 50 个', 'refresh 86 ms,18 个单例'], ['第一次使用', '5 个 127 ms,再取 0 ms'], ['总量', '代价挪到第一次使用,没有消失']], ['第一次使用'])),
    step("错误什么时候被发现。一个 @Bean 依赖没有注册的 Missing 类型。饿汉(默认):refresh() 就失败了,UnsatisfiedDependencyException。加了 @Lazy:refresh() 成功,启动没有发现问题;第一次 getBean(\"fails\") 才失败,同样是 UnsatisfiedDependencyException:No qualifying bean of type 'Missing' available。懒加载让配置错误从启动时推迟到第一次使用,可能就是上线之后的第一个请求。", t=tl(S(2)), mark=lidx(S(2), 'lazy:refresh() 成功', '第一次 getBean("fails") 才失败'), done=lidx(S(2), 'eager:refresh() 就失败了'), b=bars([['饿汉:启动阶段发现错误', 1, '是'], ['懒加载:启动阶段发现错误', 0, '否(第一次使用才发现)']], 1, done=[0], mark=[1]), kv=KV([['饿汉', '启动时就失败,部署前就能发现'], ['懒加载', '启动成功,第一次使用才失败'], ['异常', '同样是 UnsatisfiedDependencyException'], ['代价', '错误推迟到线上请求']], ['代价'])),
    step("注入点上的 @Lazy。(a)目标 Heavy 是普通单例、User 的 heavy 字段是 @Autowired @Lazy:Heavy 在 refresh 时就被构造了(第 1 条,早于 User),User 的字段是 Main$Heavy$$… 这个 CGLIB 代理;@Lazy 只推迟了解析,没有推迟目标的创建。(b)目标 Heavy 也标 @Lazy:refresh 时只构造 User,第一次调用 heavy.hi() 时才构造 Heavy。(c)目标标 @Lazy,但注入点是普通 @Autowired:构造 UserPlain 时就把 Heavy 构造出来了。要真正推迟,目标和注入点两处都要 @Lazy。", t=tl(S(3)), mark=lidx(S(3), '构造 Heavy(目标 Bean 是普通单例)', '构造 Heavy(目标 Bean 标了 @Lazy)'), done=lidx(S(3), '场景 b', '构造 User(heavy 字段是 @Lazy 注入)'), b=bars([['(a)目标普通 + 注入点 @Lazy:Heavy 在 refresh 时构造', 1, '是'], ['(b)两处都 @Lazy:Heavy 在 refresh 时构造', 0, '否(第一次调用时)'], ['(c)目标 @Lazy + 注入点普通:Heavy 在 refresh 时构造', 1, '是']], 1, mark=[0, 2], done=[1]), kv=KV([['(a)', '目标普通单例,refresh 时就构造'], ['(b)', '两处 @Lazy,第一次调用才构造'], ['(c)', '注入点普通,仍在构造 UserPlain 时创建'], ['结论', '推迟创建要目标和注入点两处都 @Lazy']], ['结论'])),
    step("懒加载的 Bean 上的 @EventListener。Lis 有两个监听方法。不管是普通单例、@Bean 方法上标 @Lazy,还是整个 @Configuration 类标 @Lazy,三种情况的时间线完全一样:Lis 在 refresh 时就被构造了(1 次),收到 ContextRefreshedEvent,之后发布的自定义事件 E1 也收到了。带 @EventListener 方法的 Bean 不会被 @Lazy 推迟,因为容器要在启动时注册监听器。", t=tl(S(4)), mark=lidx(S(4), '构造 Lis(带 @EventListener 方法)'), done=lidx(S(4), 'Lis 收到 ContextRefreshedEvent', 'Lis 收到自定义事件 E1'), b=bars([['普通单例:refresh 时构造 Lis', 1, '是'], ['@Bean @Lazy:refresh 时构造 Lis', 1, '是'], ['@Configuration @Lazy:refresh 时构造 Lis', 1, '是']], 1, done=[0, 1, 2]), kv=KV([['带 @EventListener 的 Bean', '启动时就会被创建'], ['@Lazy', '推迟不了'], ['ContextRefreshedEvent', '三种情况都收到'], ['原因', '监听器要在启动时注册(现象推断,没读源码)']], ['带 @EventListener 的 Bean'])),
    step("Boot 的全局懒加载(SpringApplication.setLazyInitialization,对应 spring.main.lazy-initialization)。false 时启动后有 22 个单例,HeavyBean 已构造;true 时只有 20 个单例,HeavyBean 没有构造。全局懒加载一次性把所有 Bean 变成 lazy,启动变快,但第二节里的“错误推迟”和第四节里的监听器等问题也跟着来。", t=tl(S(5)), mark=lidx(S(5), 'setLazyInitialization(true)'), done=lidx(S(5), 'setLazyInitialization(false)'), b=bars([['false:启动后的单例数', 22, '22'], ['true:启动后的单例数', 20, '20'], ['false:HeavyBean 已构造', 1, '是'], ['true:HeavyBean 已构造', 0, '否']], 22, done=[0, 2], mark=[1, 3]), kv=KV([['false', '22 个单例,HeavyBean 已构造'], ['true', '20 个单例,HeavyBean 未构造'], ['作用', '所有 Bean 一次性变成懒加载'], ['代价', '错误与首次请求的耗时被推迟']], ['代价'])),
]
A = mkartx('x18', 18, 'Spring,Lazy,懒加载,启动时间,真实验证,动画演示',
    '实测 @Lazy:50 个构造要 20 ms 的单例,饿汉 refresh 1263 ms、懒加载 86 ms,但第一次取其中 5 个要 127 ms;配置错误在懒加载下推迟到第一次使用才抛出;注入点 @Lazy 只推迟解析,目标和注入点两处都 @Lazy 才推迟创建;带 @EventListener 的 Bean 不会被 @Lazy 推迟;SpringApplication.setLazyInitialization(true) 让单例从 22 个变成 20 个。',
    '@Lazy 能把启动时间省多少、代价挪到了哪里?配置错误还能在启动时发现吗?注入点上的 @Lazy 和 Bean 上的 @Lazy 有什么区别?带 @EventListener 的 Bean 能不能懒加载?这篇在 Spring Framework 7.0.9 上逐项验证。',
    [('1263 → 86 ms', '50 个构造要 20 ms 的单例,饿汉与懒加载的 refresh() 耗时'), ('127 ms', '懒加载之后第一次取其中 5 个的耗时,代价被挪到第一次使用'), ('三处不推迟', '@Bean @Lazy、@Configuration @Lazy 和普通单例上的 @EventListener Bean,在 refresh 时都被构造')],
    [('省的是启动时间', '<p>懒加载把构造代价从 refresh 挪到第一次使用,总工作量不变。</p>'),
     ('错误被推迟', '<p>依赖缺失这类错误在懒加载下要到第一次使用才抛出。</p>'),
     ('注入点 @Lazy', '<p>只推迟解析,目标和注入点两处都 @Lazy 才推迟创建。</p>'),
     ('监听器', '<p>带 @EventListener 的 Bean 不会被推迟。</p>'),
     ('全局懒加载', '<p>SpringApplication.setLazyInitialization(true) 一次性让所有 Bean 懒加载。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9,第五节用 SpringApplication(WebApplicationType.NONE);Heavy 的构造器用 Thread.sleep(20) 模拟耗时,毫秒数每次运行有几 ms 抖动(例如懒加载 50 个的 refresh 在几次运行里是 66 到 86 ms);带 @EventListener 的 Bean 不被推迟是根据现象下的结论,没有读源码',
     '没有验证:Boot 的 spring.main.lazy-initialization 配置项(只验证了 SpringApplication.setLazyInitialization 这个 API);全局懒加载下用 @Lazy(false) 排除个别 Bean;@Lazy 与 @Async 代理的组合;Web 应用里懒加载对第一个请求延迟的影响;懒加载对 Actuator 健康检查的影响'],
    '@Lazy 与懒加载')
